CREATE DATABASE IF NOT EXISTS db_library
  DEFAULT CHARACTER SET utf8;
USE db_library;
SHOW DATABASES;
DROP DATABASE IF EXISTS db_test;

USE db_school;
CREATE TABLE student (
  sno   CHAR(10) NOT NULL PRIMARY KEY,
  sname VARCHAR(20) NOT NULL,
  ssex  CHAR(2) DEFAULT '男',
  sage  INT,
  sdept VARCHAR(30)
);
CREATE INDEX idx_sname ON student(sname);

ALTER TABLE student ADD COLUMN phone CHAR(11) AFTER sname;
ALTER TABLE student CHANGE COLUMN sdept dept VARCHAR(40);
ALTER TABLE student ALTER COLUMN ssex DROP DEFAULT;
ALTER TABLE student DROP COLUMN sage;

INSERT INTO S(Sno, Sname, Ssex, Sage, Sdept)
  VALUES ('2024001', '王芳', '女', 19, '计算机');
UPDATE C SET Credit = 3 WHERE Cno = 'C03';
DELETE FROM SC WHERE Sno = '2024009';
UPDATE SC SET Grade = Grade + 5
  WHERE Cno = 'C01'
    AND Sno IN (SELECT Sno FROM S WHERE Sdept = '计算机');

SELECT Sno, Sname FROM S
  WHERE Sdept = '计算机' AND Sage BETWEEN 18 AND 20;
SELECT * FROM S WHERE Sname LIKE '李%';
SELECT Sdept, COUNT(*) AS 人数 FROM S GROUP BY Sdept;
SELECT Sdept FROM S
  GROUP BY Sdept HAVING COUNT(*) > 100;

SELECT Sno, Grade FROM SC
  WHERE Cno = 'C01' ORDER BY Grade DESC;
SELECT Cno, COUNT(*) AS 人数, AVG(Grade) AS 平均成绩
  FROM SC GROUP BY Cno;
SELECT Sno, AVG(Grade) AS 平均成绩 FROM SC
  GROUP BY Sno HAVING AVG(Grade) >= 85;
SELECT * FROM SC WHERE Cno = 'C02'
  ORDER BY Grade DESC LIMIT 3;

SELECT S.Sno, Sname, Grade
  FROM S JOIN SC ON S.Sno = SC.Sno
         JOIN C ON SC.Cno = C.Cno
  WHERE Cname = '数据库原理';
SELECT Sno, Sname FROM S
  WHERE Sno NOT IN (SELECT Sno FROM SC);
SELECT Sname FROM S
  WHERE Sage > ALL (SELECT Sage FROM S WHERE Sdept = '计算机');

CREATE VIEW v_cs AS
  SELECT Sno, Sname, Sage FROM S
  WHERE Sdept = '计算机'
  WITH CHECK OPTION;
SELECT * FROM v_cs WHERE Sage < 20;
CREATE VIEW v_avg(Sno, avg_grade) AS
  SELECT Sno, AVG(Grade) FROM SC GROUP BY Sno;
DROP VIEW v_cs;
